CREATE   VIEW [CE].[vwSalesOrder]
AS 
SELECT 
	[SalesOrderId],
	[AccountId],
	ISNULL([ContactId], [ricsv1_ProductOwner]) AS [ContactId],
	[OpportunityId],
	[ricsv1_isrenewalofsubscription],
	[TransactionCurrencyIdName],
	[isocurrencycode],
	[ricsv1_TransactionId],
	[OrderNumber],
	[ModifiedBy],
	[ModifiedByName],
	[ModifiedOnBehalfBy],
	[ModifiedOnBehalfByName],
	[CreatedBy],
	[CreatedByName],
	[ricsv1_ProductOwner],
	[ricsv1_ProductOwnerName],
	[OwnerId],
	[OwnerIdName],
	[Name],
	[Description],
	[DiscountAmount],
	[DiscountAmount_Base],
	[FreightAmount],
	[FreightAmount_Base],
	[TotalAmount],
	[TotalAmount_Base],
	[TotalLineItemAmount],
	[TotalLineItemAmount_Base],
	[TotalLineItemDiscountAmount],
	[TotalLineItemDiscountAmount_Base],
	[TotalAmountLessFreight],
	[TotalAmountLessFreight_Base],
	[TotalDiscountAmount],
	[TotalDiscountAmount_Base],
	[TotalTax],
	[TotalTax_Base],
	[apuk_lionheartdonation],
	[apuk_lionheartdonation_base],
	[ExchangeRate],
	[ricsv1_PaymentMethod],
	[PaymentMethod_Description],
	[ricsv1_SubscriptionRenewal],
	[ricsv1_SubscriptionRenewal_Description],
	[CreatedOn],
	[ModifiedOn],
	[StateCode],
	[StateCode_Description],
	[StatusCode],
	[StatusCode_Description],
	[customerid],
	[CustomerIdName],
	[CustomerIdType],
	[DateFulfilled],
	[apuk_eventcode],
	[CampaignId],
	[quoteid],
	[apuk_firmreinbursessubs],
	'CE' AS [Source]
FROM [synapse_ce].[vwSalesOrder]
